// Time: O(n)   Space: O(distinct values)

fun hasDuplicate(nums: IntArray): Boolean {
    val seen = HashSet<Int>()
    for (x in nums) {
        if (!seen.add(x)) return true          // add returns false when already present
    }
    return false
}
// Time: O(n)   Space: O(n)

fun twoSum(nums: IntArray, target: Int): IntArray {
    val indexOf = HashMap<Int, Int>()          // value -> index
    for ((i, x) in nums.withIndex()) {
        val need = target - x
        indexOf[need]?.let { return intArrayOf(it, i) }
        indexOf[x] = i                         // add AFTER checking to avoid using x twice
    }
    return intArrayOf()
}
// Time: O(n)   Space: O(n)

fun groupAnagrams(strs: Array<String>): List<List<String>> {
    val groups = HashMap<String, MutableList<String>>()
    for (s in strs) {
        val key = String(s.toCharArray().also { it.sort() })    // sorted letters as the key
        groups.getOrPut(key) { mutableListOf() }.add(s)
    }
    return groups.values.toList()
}
// Time: O(n * L log L)   Space: O(n * L)

fun isAnagram(s: String, t: String): Boolean {
    if (s.length != t.length) return false
    val count = IntArray(26)
    for (i in s.indices) {
        count[s[i] - 'a']++
        count[t[i] - 'a']--
    }
    return count.all { it == 0 }
}
// Time: O(n)   Space: O(1)

fun firstUniqChar(s: String): Int {
    val count = IntArray(26)
    for (c in s) count[c - 'a']++
    for (i in s.indices) {
        if (count[s[i] - 'a'] == 1) return i
    }
    return -1
}
// Time: O(n)   Space: O(1)

fun containsNearbyDuplicate(nums: IntArray, k: Int): Boolean {
    val lastSeen = HashMap<Int, Int>()
    for ((i, x) in nums.withIndex()) {
        val prev = lastSeen[x]
        if (prev != null && i - prev <= k) return true
        lastSeen[x] = i
    }
    return false
}
// Time: O(n)   Space: O(n)

fun longestConsecutive(nums: IntArray): Int {
    val set = nums.toHashSet()
    var best = 0
    for (x in set) {
        if ((x - 1) !in set) {                  // x is the start of a sequence
            var length = 1
            var cur = x
            while ((cur + 1) in set) {
                cur++
                length++
            }
            best = maxOf(best, length)
        }
    }
    return best
}
// Time: O(n)   Space: O(n)
// Each number is visited at most twice because we only start at sequence beginnings

fun subarraySum(nums: IntArray, k: Int): Int {
    val count = HashMap<Int, Int>()
    count[0] = 1
    var sum = 0
    var result = 0
    for (x in nums) {
        sum += x
        result += count[sum - k] ?: 0
        count[sum] = (count[sum] ?: 0) + 1
    }
    return result
}
// Time: O(n)   Space: O(n)

fun isIsomorphic(s: String, t: String): Boolean {
    if (s.length != t.length) return false
    val st = HashMap<Char, Char>()
    val ts = HashMap<Char, Char>()
    for (i in s.indices) {
        val a = s[i]
        val b = t[i]
        if (st.containsKey(a) && st[a] != b) return false
        if (ts.containsKey(b) && ts[b] != a) return false
        st[a] = b
        ts[b] = a
    }
    return true
}
// Time: O(n)   Space: O(1) for a fixed alphabet

fun wordPattern(pattern: String, s: String): Boolean {
    val words = s.split(" ")
    if (pattern.length != words.size) return false
    val charToWord = HashMap<Char, String>()
    val wordToChar = HashMap<String, Char>()
    for (i in pattern.indices) {
        val c = pattern[i]
        val w = words[i]
        if (charToWord.getOrPut(c) { w } != w) return false
        if (wordToChar.getOrPut(w) { c } != c) return false
    }
    return true
}
// Time: O(n)   Space: O(n)

fun intersect(nums1: IntArray, nums2: IntArray): IntArray {
    val count = HashMap<Int, Int>()
    for (x in nums1) count[x] = (count[x] ?: 0) + 1
    val result = mutableListOf<Int>()
    for (x in nums2) {
        val c = count[x] ?: 0
        if (c > 0) {
            result.add(x)
            count[x] = c - 1
        }
    }
    return result.toIntArray()
}
// Time: O(n + m)   Space: O(min(n, m))

fun fourSumCount(a: IntArray, b: IntArray, c: IntArray, d: IntArray): Int {
    val sums = HashMap<Int, Int>()
    for (x in a) for (y in b) {
        val s = x + y
        sums[s] = (sums[s] ?: 0) + 1
    }
    var count = 0
    for (x in c) for (y in d) {
        count += sums[-(x + y)] ?: 0
    }
    return count
}
// Time: O(n²)   Space: O(n²)
// Meet in the middle: n⁴ becomes two n² passes

fun topKFrequent(words: Array<String>, k: Int): List<String> {
    val freq = HashMap<String, Int>()
    for (w in words) freq[w] = (freq[w] ?: 0) + 1
    return freq.keys
        .sortedWith(compareByDescending<String> { freq[it] }.thenBy { it })
        .take(k)
}
// Time: O(n log n)   Space: O(n)
// Use a heap of size k for O(n log k)

fun findRestaurant(list1: Array<String>, list2: Array<String>): Array<String> {
    val index = HashMap<String, Int>()
    for ((i, s) in list1.withIndex()) index[s] = i
    var best = Int.MAX_VALUE
    val result = mutableListOf<String>()
    for ((j, s) in list2.withIndex()) {
        val i = index[s] ?: continue
        val sum = i + j
        if (sum < best) { best = sum; result.clear(); result.add(s) }
        else if (sum == best) result.add(s)
    }
    return result.toTypedArray()
}
// Time: O(n + m)   Space: O(n)

class LRUCache(private val capacity: Int) {
    private val map = LinkedHashMap<Int, Int>()

    fun get(key: Int): Int {
        val value = map.remove(key) ?: return -1
        map[key] = value                         // re-insert to mark as most recent
        return value
    }

    fun put(key: Int, value: Int) {
        map.remove(key)
        map[key] = value
        if (map.size > capacity) {
            val oldest = map.keys.first()        // first key is the least recently used
            map.remove(oldest)
        }
    }
}
// get / put: O(1) average   Space: O(capacity)

class RandomizedSet {
    private val list = ArrayList<Int>()
    private val index = HashMap<Int, Int>()          // value -> position in list

    fun insert(v: Int): Boolean {
        if (v in index) return false
        index[v] = list.size
        list.add(v)
        return true
    }

    fun remove(v: Int): Boolean {
        val pos = index[v] ?: return false
        val last = list.last()
        list[pos] = last                             // move last into the gap
        index[last] = pos
        list.removeAt(list.lastIndex)
        index.remove(v)
        return true
    }

    fun getRandom(): Int = list[(0 until list.size).random()]
}
// All operations: O(1) average

